const input = $json.body ?? $json;
const stationName = String(input.station_name ?? '').trim();
const lunchDate = String(input.lunch_date ?? '').trim();
const lunchTime = String(input.lunch_time ?? '').trim();

if (!stationName) throw new Error('station_name は必須です');
if (!/^\d{4}-\d{2}-\d{2}$/.test(lunchDate)) throw new Error('lunch_date は YYYY-MM-DD 形式で指定してください');
if (!/^\d{2}:\d{2}$/.test(lunchTime)) throw new Error('lunch_time は HH:mm 形式で指定してください');

return [{ json: {
  station_name: stationName,
  station_query: stationName.endsWith('駅') ? stationName : `${stationName}駅`,
  lunch_date: lunchDate,
  lunch_time: lunchTime,
  max_walk_minutes: Number(input.max_walk_minutes ?? 10),
  min_rating: Number(input.min_rating ?? 3.5),
  output_format: String(input.output_format ?? 'markdown').toLowerCase() === 'html' ? 'html' : 'markdown'
}}];

const config = $json;

function requireEnv(name) {
  const value = process.env[name];
  if (!value) throw new Error(`${name} が未設定です`);
  return value;
}

function toQuery(params) {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== null && value !== '') {
      search.set(key, String(value));
    }
  }
  return search.toString();
}

async function callJson(url, options = {}) {
  const response = await fetch(url, options);
  const text = await response.text();
  const data = JSON.parse(text);
  if (!response.ok) throw new Error(`HTTP ${response.status}: ${text.slice(0, 300)}`);
  return data;
}

const apiKey = requireEnv('GOOGLE_MAPS_API_KEY');
const geocode = await callJson(`https://maps.googleapis.com/maps/api/geocode/json?${toQuery({ address: `${config.station_query} 日本`, key: apiKey })}`);
if (!Array.isArray(geocode.results) || geocode.results.length === 0) {
  throw new Error('駅名を特定できませんでした。駅名に「駅」を付けるか、都道府県名を追加してください。');
}

const station = geocode.results[0];
const stationLat = station.geometry.location.lat;
const stationLng = station.geometry.location.lng;
const nearby = await callJson(`https://maps.googleapis.com/maps/api/place/nearbysearch/json?${toQuery({ location: `${stationLat},${stationLng}`, radius: 1200, type: 'restaurant', language: 'ja', key: apiKey })}`);

const results = (nearby.results ?? []).slice(0, 5).map((shop) => ({
  name: shop.name,
  rating: shop.rating ?? null,
  address: shop.vicinity ?? null,
  place_id: shop.place_id ?? null
}));

return [{ json: {
  station_name: config.station_name,
  lunch_date: config.lunch_date,
  lunch_time: config.lunch_time,
  output_format: config.output_format,
  rendered_content: JSON.stringify(results, null, 2),
  result_json: { recommended: results, conditional: [], avoid: [] }
}}];
